/**
 * Zod schemas of the rows of the model's tables, generated by IFC SQL Aide. Do not edit: change the model and generate again.
 *
 * @module
 */
import { z } from "zod";

/** A calendar date, as a driver of IFC SQL Aide gives it. */
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);

/** The kinds of party: a person or an organization */
export const PartyKind = z.object({
  code: z.string(),
  label: z.string(),
  description: z.string().nullable(),
});

/** The roles a party may play, such as customer, supplier or employee */
export const PartyRoleKind = z.object({
  code: z.string(),
  label: z.string(),
  description: z.string().nullable(),
});

/** The ways one party may be related to another */
export const PartyRelationKind = z.object({
  code: z.string(),
  label: z.string(),
  description: z.string().nullable(),
});

/** The kinds of identifier a party may hold */
export const PartyIdentifierKind = z.object({
  code: z.string(),
  label: z.string(),
  description: z.string().nullable(),
});

/** A party: anyone or anything a business deals with as one, whether a person or an organization. What is true of both is here; what is true of one only is in `person` or `organization`, under the same key. */
export const Party = z.object({
  party_id: z.string(),
  party_kind_code: z.string(),
  display_name: z.string(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** A person: a party who is a human being. Their key is their party's key. */
export const Person = z.object({
  party_id: z.string(),
  given_name: z.string(),
  family_name: z.string(),
  birth_date: isoDate.nullable(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** An organization: a party that is a company, an agency, a club or any other body. Its key is its party's key. */
export const Organization = z.object({
  party_id: z.string(),
  legal_name: z.string(),
  founded_on: isoDate.nullable(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** A role a party plays for a time: the same party may be a customer and a supplier at once. */
export const PartyRole = z.object({
  party_role_id: z.string(),
  party_id: z.string(),
  party_role_kind_code: z.string(),
  valid_from: isoDate,
  valid_to: isoDate.nullable(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** A relation between two parties for a time, read from the first to the second: Ada is employed by Analytical Engines. */
export const PartyRelation = z.object({
  party_relation_id: z.string(),
  from_party_id: z.string(),
  to_party_id: z.string(),
  party_relation_kind_code: z.string(),
  valid_from: isoDate,
  valid_to: isoDate.nullable(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** An identifier a party holds, as someone else issued it: a tax number, a passport number. A party holds one of a kind once. */
export const PartyIdentifier = z.object({
  party_identifier_id: z.string(),
  party_id: z.string(),
  party_identifier_kind_code: z.string(),
  identifier: z.string(),
  issued_by: z.string().nullable(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** A way to reach a party over a network: an email address, a telephone number, a web address. */
export const ElectronicContact = z.object({
  electronic_contact_id: z.string(),
  party_id: z.string(),
  medium: z.enum(["email", "telephone", "web"]),
  address: z.string(),
  is_primary: z.boolean(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});

/** A place a party receives post or may be visited. */
export const PostalAddress = z.object({
  postal_address_id: z.string(),
  party_id: z.string(),
  purpose: z.enum(["home", "work", "billing", "delivery"]),
  line_1: z.string(),
  line_2: z.string().nullable(),
  locality: z.string(),
  region: z.string().nullable(),
  postal_code: z.string().nullable(),
  country_code: z.string(),
  created_at: z.date(),
  created_by: z.string().nullable(),
  updated_at: z.date().nullable(),
  updated_by: z.string().nullable(),
  deleted_at: z.date().nullable(),
  deleted_by: z.string().nullable(),
});
